SELECT COUNTER_ID id, COUNTER_NAME text, CASE WHEN COUNTER_TYPE=#{COUNTER_TYPE} THEN #{YES_NO_N} ELSE #{YES_NO_Y} END object FROM MST_COUNTER_PARTY where 1=1
AND not exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = MST_COUNTER_PARTY.COUNTER_ID) and NOT EXISTS (SELECT 1 FROM fin_product p WHERE p.FINPROD_MARKET_ID = MST_COUNTER_PARTY.COUNTER_ID)
AND exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = MST_COUNTER_PARTY.COUNTER_ID)
AND ( COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND COUNTER_ID = #{initValue}
AND( COUNTER_TYPE = #{counterType} OR( COUNTER_ID IN
null) or COUNTER_ID in (
#{item}
))
AND COUNTER_TYPE = #{counterType}

SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text FROM MST_COUNTER_PARTY T1 INNER JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID
( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
T1.COUNTER_ID = #{initValue}
And T2.IS_ASSTE_MANAGER = #{isAssteManager}
